import java.util.*;

public class Main {
    int titleToNumber(String columnTitle) {
        int n = columnTitle.length();
        long total = 0;
        for (int i = 0; i < n; i++) {                    // i counts positions from the right, starting at 0
            int letterValue = columnTitle.charAt(n - 1 - i) - 'A' + 1;
            long power = 1;
            for (int k = 0; k < i; k++) {
                power *= 26;                                // recompute 26 to the power of i from scratch
            }
            total += letterValue * power;
        }
        return (int) total;
    }

    public static void main(String[] args) {
        String columnTitle = "ZY";
        Main solution = new Main();
        System.out.println(solution.titleToNumber(columnTitle));
    }
}

