import java.util.*;

public class Main {
    int titleToNumber(String columnTitle) {
        int result = 0;
        for (char ch : columnTitle.toCharArray()) {       // read the title from left to right
            int letterValue = ch - 'A' + 1;
            result = result * 26 + letterValue;              // shift left in base 26, add this letter directly
        }
        return result;
    }

    public static void main(String[] args) {
        String columnTitle = "ZY";
        Main solution = new Main();
        System.out.println(solution.titleToNumber(columnTitle));
    }
}

